const TH_ALIAS: Record<string, string> = {"กรุงเทพ":"กรุงเทพมหานคร","กรุงเทพฯ":"กรุงเทพมหานคร","กทม":"กรุงเทพมหานคร","กทม.":"กรุงเทพมหานคร","บางกอก":"กรุงเทพมหานคร","อยุธยา":"พระนครศรีอยุธยา","โคราช":"นครราชสีมา","ศรีษะเกษ":"ศรีสะเกษ"}

// จับคู่ค่า province (free-text) → ชื่อจังหวัดมาตรฐาน ; คืน null ถ้าจับไม่ได้
export function matchProvince(raw: string | null | undefined): string | null {
  if (!raw) return null
  let s = String(raw).trim()
  if (!s) return null
  // ตัดคำนำหน้า "จังหวัด" / "จ." / "จ "
  s = s.replace(/^จังหวัด\s*/, '').replace(/^จ\.?\s*/, '').trim()
  if (CANON_SET.has(s)) return s
  const noSpace = s.replace(/\s+/g, '')
  if (CANON_SET.has(noSpace)) return noSpace
  if (TH_ALIAS[s]) return TH_ALIAS[s]
  if (TH_ALIAS[noSpace]) return TH_ALIAS[noSpace]
  const lower = s.toLowerCase().replace(/\s+/g, ' ').trim()
  if (EN2TH[lower]) return EN2TH[lower]
  if (EN2TH[lower.replace(/\s+/g, '')]) return EN2TH[lower.replace(/\s+/g, '')]
  return null
}
